mapper.select:
SELECT n.notification_id AS notificationId, n.batch_id AS batchId, n.recipient_user_id AS recipientUserId, n.sender_user_id AS senderUserId, sender.nickname AS senderNickname, n.notification_type AS notificationType, n.title, n.body, n.target_type AS targetType, n.target_id AS targetId, n.read_yn AS readYn, n.hidden_yn AS hiddenYn, n.created_at AS createdAt, n.read_at AS readAt, n.expires_at AS expiresAt FROM notification n LEFT JOIN user_account sender ON sender.user_id = n.sender_user_id WHERE n.recipient_user_id = #{userId} AND n.hidden_yn = 'N' AND n.created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) AND (n.expires_at IS NULL OR n.expires_at >= NOW())
AND n.read_yn = 'N'
ORDER BY n.created_at DESC, n.notification_id DESC LIMIT #{limit}

mapper.update:
UPDATE notification
SET read_yn = 'Y',
    read_at = COALESCE(read_at, NOW())
WHERE notification_id = #{notificationId}
  AND recipient_user_id = #{userId}

UPDATE notification
SET hidden_yn = 'Y'
WHERE notification_id = #{notificationId}
  AND recipient_user_id = #{userId}
